-- Воронка продаж СнабТех'26: сделки из «Свода по воронке СнабТех 26» (лист «воронка», 293 сделки).
-- Статусы «0. Отказ» … «5. Оплачен» → этапы воронки. Этап отказа в своде не указан: отказ со
-- суммой считается отказом на «Переговорах» (клиенту называли цену), без суммы — на «Квалификации».
-- Сделки с билетами относятся к направлению «Участник». Оплаченные сделки появятся в «Доходах» → «Факт»
-- как предложения, в факт они сами не попадают.
-- Форум ищется по «СнабТех» в названии без «Бизнес-миссия» и «Китай»; если таких не ровно один
-- или в воронке форума уже есть сделки — ничего не меняется.
DO $$
DECLARE
  fid INTEGER;
  cnt INTEGER;
BEGIN
  SELECT count(*), min("id") INTO cnt, fid
  FROM "Forum"
  WHERE "name" ~ '[Сс][Нн][Аа][Бб][ -]?[Тт][Ее][Хх]'
    AND "name" !~ '[Мм][Ии][Сс][Сс][Ии][Яя]'
    AND "name" !~ '[Кк][Ии][Тт][Аа][Йй]';

  IF cnt <> 1 THEN
    RAISE NOTICE 'Воронка СнабТех: найдено форумов % — сделки не загружены', cnt;
    RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM "Deal" WHERE "forumId" = fid) THEN
    RAISE NOTICE 'Воронка СнабТех: сделки уже есть — пропущено';
    RETURN;
  END IF;

